public abstract record Result<T, TError>
{
    public sealed record Ok(T Value) : Result<T, TError>;
    public sealed record Err(TError Error) : Result<T, TError>;
}

public static Result<int, string> ParsePort(string s) =>
    int.TryParse(s, out var v) ? new Result<int, string>.Ok(v) : new Result<int, string>.Err("bad");

var text = ParsePort(raw) switch {
    Result<int, string>.Ok ok   => $"port {ok.Value}",
    Result<int, string>.Err bad => $"failed: {bad.Error}",
};

